"use server";

import { generateProjectDescription, GenerateProjectDescriptionInput } from "@/ai/flows/generate-project-description";
import { z } from "zod";

const formSchema = z.object({
  keywords: z.string().min(3, "Please enter at least 3 characters."),
});

export async function generateProjectDescriptionAction(values: z.infer<typeof formSchema>) {
  const validatedInput = formSchema.safeParse(values);

  if (!validatedInput.success) {
    return { success: false, error: "Invalid input." };
  }
  
  try {
    const result = await generateProjectDescription({ keywords: validatedInput.data.keywords });
    return { success: true, description: result.description };
  } catch (error) {
    console.error("Error generating project description:", error);
    return { success: false, error: "Failed to generate description. Please try again." };
  }
}
